module fifo_01 (
  input clk,
  input rst_n,
  input wr_en,
  input [7:0] wr_data,
  input rd_en,
  output [7:0] rd_data,
  output full,
  output empty
);

  // FIFO parameters
  localparam DEPTH = 8;
  localparam ADDR_WIDTH = 3;

  // FIFO memory array
  reg [7:0] mem [0:DEPTH-1];

  // Read and write pointers
  reg [ADDR_WIDTH-1:0] wr_ptr;
  reg [ADDR_WIDTH-1:0] rd_ptr;

  // Counter to track number of elements
  reg [ADDR_WIDTH:0] count;

  // Full and empty flags
  assign full = (count == DEPTH);
  assign empty = (count == 0);

  // Read data output
  assign rd_data = mem[rd_ptr];

  // Write process
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      wr_ptr <= '0;
      rd_ptr <= '0;
      count <= '0;
    end else begin
      if (wr_en && !full) begin
        mem[wr_ptr] <= wr_data;
        wr_ptr <= wr_ptr + 1'b1;
        count <= count + 1'b1;
      end

      if (rd_en && !empty) begin
        rd_ptr <= rd_ptr + 1'b1;
        count <= count - 1'b1;
      end
    end
  end

endmodule

